<!doctype html>
<html lang="en">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clinic Patient Records</title>
<style>
*{box-sizing:border-box}body{margin:0;font:12px Arial;color:#212529;background:#f3f6fa}.navbar{height:41px;background:#0d6efd;color:#fff}.nav-content,.container{max-width:846px;margin:auto}.nav-content{height:100%;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:bold;font-size:14px}.nav-links{display:flex;gap:8px}.nav-links a{color:#fff;border:1px solid #fff;border-radius:3px;padding:5px 8px;text-decoration:none;font-size:10px}.nav-links .register{background:#fff;color:#212529}.container{margin-top:26px}.page-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:17px}h1{font-size:23px;margin:0 0 5px}.subtitle,.stats-label,.table-footer{color:#687384}.subtitle{margin:0}.primary-btn{background:#0d6efd;color:#fff;border:1px solid #0d6efd;border-radius:4px;padding:8px 12px;cursor:pointer;font-size:11px}.stats-card,.table-card{background:#fff;border-radius:10px;box-shadow:0 3px 12px #182c4410}.stats-card{width:270px;padding:15px 12px 11px;margin-bottom:17px}.stats-label{margin-bottom:5px}.stats-number{color:#0d6efd;font-size:24px;font-weight:bold}.table-card{padding:17px}.search-form{display:flex;gap:6px;margin-bottom:17px}.search-form input{flex:1;height:29px;padding:6px 9px;border:1px solid #d7dde5;border-radius:4px}.clear-btn,.cancel-btn{background:#fff;border:1px solid #7b8794;border-radius:4px;padding:6px 10px;cursor:pointer}.table-wrapper{overflow-x:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:11px}th,td{text-align:left;padding:7px 6px;border-bottom:1px solid #dce1e7}thead{background:#f8f9fa}.action-buttons,.pagination{display:flex;gap:4px}.action-btn,.pagination button{background:#fff;border:1px solid #dce1e7;padding:4px 6px;cursor:pointer;font-size:10px}.view-btn{color:#0dcaf0;border-color:#0dcaf0}.edit-btn{color:#0d6efd;border-color:#0d6efd}.delete-btn{color:#dc3545;border-color:#dc3545}.table-footer{display:flex;justify-content:space-between;margin-top:12px}.pagination button{min-width:27px;height:28px;color:#0d6efd}.pagination .active{background:#0d6efd;color:#fff}.modal{display:none;position:fixed;inset:0;background:#0007;justify-content:center;align-items:center;padding:15px}.modal.show{display:flex}.modal-content{background:#fff;padding:22px;border-radius:8px;width:100%;max-width:450px}.form-group{margin-bottom:12px}.form-group label{display:block;margin-bottom:5px;font-weight:bold}.form-group input,.form-group select{width:100%;padding:9px;border:1px solid #ced4da;border-radius:4px}.form-actions{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}.details p{border-bottom:1px solid #eee;padding-bottom:8px}.empty-message{text-align:center;padding:25px}@media(max-width:900px){.nav-content,.container{width:calc(100% - 30px)}}@media(max-width:600px){.page-heading{align-items:flex-start;gap:12px}.stats-card{width:100%}.table-footer{flex-direction:column;gap:10px}}
</style></head>
<body>
<nav class="navbar"><div class="nav-content"><div class="brand">Clinic Patient Records</div><div class="nav-links"><a href="#" onclick="return false">Patient List</a><a class="register" href="#register" onclick="openRegister();return false">+ Register Patient</a></div></div></nav>
<main class="container"><div class="page-heading"><div><h1>Patient Records</h1><p class="subtitle">Manage registered clinic patients.</p></div><button class="primary-btn" onclick="openRegister()">+ Register New Patient</button></div><div class="stats-card"><div class="stats-label">Total Registered Patients</div><div class="stats-number" id="totalPatients">0</div></div><section class="table-card"><form class="search-form" id="searchForm"><input id="searchInput" placeholder="Search patient number or name..."><button class="primary-btn">Search</button><button type="button" class="clear-btn" onclick="clearSearch()">Clear</button></form><div class="table-wrapper"><table><thead><tr><th>Patient No.</th><th>Full Name</th><th>Birth Date</th><th>Sex</th><th>Contact Number</th><th>Actions</th></tr></thead><tbody id="patientTable"></tbody></table></div><div class="table-footer"><span id="recordInfo"></span><div class="pagination" id="pagination"></div></div></section></main>
<div class="modal" id="patientModal"><div class="modal-content"><h2 id="modalTitle">Register New Patient</h2><form id="patientForm"><div class="form-group"><label>Patient Number</label><input id="patientNo" required></div><div class="form-group"><label>Full Name</label><input id="fullName" required></div><div class="form-group"><label>Birth Date</label><input id="birthDate" type="date" required></div><div class="form-group"><label>Sex</label><select id="sex" required><option value="">Select sex</option><option>Male</option><option>Female</option></select></div><div class="form-group"><label>Contact Number</label><input id="contact" required></div><div class="form-actions"><button type="button" class="cancel-btn" onclick="closeModal()">Cancel</button><button class="primary-btn">Save Patient</button></div></form></div></div><div class="modal" id="viewModal"><div class="modal-content"><h2>Patient Information</h2><div class="details" id="patientDetails"></div><div class="form-actions"><button class="primary-btn" onclick="closeView()">Close</button></div></div></div>
<script>
let patients=[{no:'00010',name:'Aguilar, Rhaymar',birth:'2005-11-10',sex:'Male',contact:'09129588266'},{no:'P0002',name:'Alabasta, Jane',birth:'2026-10-11',sex:'Female',contact:'0917888888888'},{no:'P0009',name:'Barrantes, Jelliane',birth:'2006-07-11',sex:'Female',contact:'09876345624'},{no:'P0067',name:'Dauz, Jasmine Kaye',birth:'2006-01-11',sex:'Female',contact:'9690302687'},{no:'P0001',name:'Dela Cruz, Juan',birth:'2026-10-01',sex:'Male',contact:'0919123456789'},{no:'P0099',name:'Domenek, Jolyos',birth:'2000-01-01',sex:'Male',contact:'03123456789'},{no:'1',name:'Fajardo, Haidie',birth:'2006-10-13',sex:'Female',contact:'09090909090'},{no:'5',name:'hidalgo, denver',birth:'2006-07-07',sex:'Male',contact:'09619559963'},{no:'P0011',name:'Letran, Aleina Lyme',birth:'2006-06-14',sex:'Female',contact:'09850032726'},{no:'P0003',name:'Monis, Crizel',birth:'2026-01-29',sex:'Female',contact:'09707169672'},{no:'P0012',name:'Reyes, Maria',birth:'2004-05-15',sex:'Female',contact:'09123456780'},{no:'P0013',name:'Santos, Mark',birth:'2003-08-21',sex:'Male',contact:'09123456781'},{no:'P0014',name:'Torres, Ana',birth:'2005-03-18',sex:'Female',contact:'09123456782'},{no:'P0015',name:'Villanueva, Carlo',birth:'2002-12-09',sex:'Male',contact:'09123456783'}];let filtered=[...patients],page=1,editing=null;const $=id=>document.getElementById(id),date=d=>new Date(d+'T00:00:00').toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric'});
function render(){ $('totalPatients').textContent=patients.length;let pages=Math.max(1,Math.ceil(filtered.length/10));page=Math.min(page,pages);let start=(page-1)*10,rows=filtered.slice(start,start+10),t=$('patientTable');t.innerHTML='';if(!rows.length)t.innerHTML='<tr><td colspan="6" class="empty-message">No patient records found.</td></tr>';rows.forEach(p=>{let i=patients.indexOf(p),tr=document.createElement('tr');[p.no,p.name,date(p.birth),p.sex,p.contact].forEach(v=>{let c=document.createElement('td');c.textContent=v;tr.append(c)});let c=document.createElement('td'),a=document.createElement('div');a.className='action-buttons';[['View','view-btn',()=>view(i)],['Edit','edit-btn',()=>edit(i)],['Delete','delete-btn',()=>del(i)]].forEach(([l,cl,f])=>{let b=document.createElement('button');b.textContent=l;b.className='action-btn '+cl;b.onclick=f;a.append(b)});c.append(a);tr.append(c);t.append(tr)});$('recordInfo').textContent=`Showing ${filtered.length?start+1:0} to ${Math.min(start+10,filtered.length)} of ${filtered.length} records`;$('pagination').innerHTML='';for(let n=1;n<=pages;n++){let b=document.createElement('button');b.textContent=n;b.className=n===page?'active':'';b.onclick=()=>{page=n;render()};$('pagination').append(b)}}
$('searchForm').onsubmit=e=>{e.preventDefault();let q=$('searchInput').value.toLowerCase().trim();filtered=patients.filter(p=>p.no.toLowerCase().includes(q)||p.name.toLowerCase().includes(q));page=1;render()};function clearSearch(){$('searchInput').value='';filtered=[...patients];page=1;render()}function openRegister(){editing=null;$('patientForm').reset();$('patientNo').readOnly=false;$('modalTitle').textContent='Register New Patient';$('patientModal').classList.add('show')}function closeModal(){$('patientModal').classList.remove('show')}
function edit(i){let p=patients[i];editing=i;[['patientNo','no'],['fullName','name'],['birthDate','birth'],['sex','sex'],['contact','contact']].forEach(([id,k])=>$(id).value=p[k]);$('patientNo').readOnly=true;$('modalTitle').textContent='Edit Patient Information';$('patientModal').classList.add('show')}$('patientForm').onsubmit=e=>{e.preventDefault();let p={no:$('patientNo').value.trim(),name:$('fullName').value.trim(),birth:$('birthDate').value,sex:$('sex').value,contact:$('contact').value.trim()};if(editing===null){if(patients.some(x=>x.no.toLowerCase()===p.no.toLowerCase()))return alert('This patient number already exists.');patients.push(p)}else patients[editing]=p;filtered=[...patients];page=Math.ceil(filtered.length/10);closeModal();render()};function view(i){let p=patients[i];$('patientDetails').innerHTML='';[['Patient Number',p.no],['Full Name',p.name],['Birth Date',date(p.birth)],['Sex',p.sex],['Contact Number',p.contact]].forEach(([l,v])=>{let e=document.createElement('p');e.innerHTML='<strong>'+l+': </strong>'+v;$('patientDetails').append(e)});$('viewModal').classList.add('show')}function closeView(){$('viewModal').classList.remove('show')}function del(i){if(confirm('Delete patient "'+patients[i].name+'"?')){patients.splice(i,1);filtered=[...patients];render()}}render();
</script></body></html>
